<template><div class="settings-grid"><a-card class="panel-card" title="TMDB 设置"><a-form layout="vertical"><a-form-item label="API Key"><a-input-password v-model:value="tmdb.tmdb_api_key"/></a-form-item><a-form-item label="Access Token"><a-input-password v-model:value="tmdb.tmdb_access_token"/></a-form-item><a-form-item label="API 地址"><a-input v-model:value="tmdb.tmdb_url"/></a-form-item><a-form-item label="图片地址"><a-input v-model:value="tmdb.tmdb_image_url"/></a-form-item><a-row :gutter="12"><a-col :span="12"><a-form-item label="元数据语言"><a-input v-model:value="tmdb.tmdb_language"/></a-form-item></a-col><a-col :span="12"><a-form-item label="图片语言"><a-input v-model:value="tmdb.tmdb_image_language"/></a-form-item></a-col></a-row><a-checkbox v-model:checked="tmdb.tmdb_enable_proxy">使用系统代理</a-checkbox><div class="actions"><a-button @click="testTmdb">测试</a-button><a-button type="primary" @click="saveTmdb">保存</a-button></div></a-form></a-card><a-card class="panel-card" title="AI 识别"><a-form layout="vertical"><a-form-item label="接口地址"><a-input v-model:value="ai.ai_base_url"/></a-form-item><a-form-item label="API Key"><a-input-password v-model:value="ai.ai_api_key"/></a-form-item><a-row :gutter="12"><a-col :span="12"><a-form-item label="模型"><a-input v-model:value="ai.ai_model_name"/></a-form-item></a-col><a-col :span="12"><a-form-item label="超时（秒）"><a-input-number v-model:value="ai.ai_timeout" style="width:100%"/></a-form-item></a-col></a-row><a-form-item label="自定义提示词"><a-textarea v-model:value="ai.ai_prompt" :rows="5"/></a-form-item><div class="actions"><a-button @click="testAi">测试</a-button><a-button type="primary" @click="saveAi">保存</a-button></div></a-form></a-card></div><a-card class="panel-card categories" title="媒体分类策略"><template #extra><a-space><a-button @click="openCategory('movie')">电影分类</a-button><a-button @click="openCategory('tvshow')">剧集分类</a-button></a-space></template><a-row :gutter="18"><a-col :xs="24" :lg="12"><a-list header="电影" :data-source="movie"><template #renderItem="{item}"><a-list-item><a-list-item-meta :title="item.name" :description="[...(item.language_array||[]),...(item.genre_id_array||[])].join(', ')"/><a-popconfirm title="确定删除？" @confirm="removeCategory('movie',item.id)"><a-button danger type="text">删除</a-button></a-popconfirm></a-list-item></template></a-list></a-col><a-col :xs="24" :lg="12"><a-list header="电视剧" :data-source="tv"><template #renderItem="{item}"><a-list-item><a-list-item-meta :title="item.name" :description="[...(item.country_array||[]),...(item.genre_id_array||[])].join(', ')"/><a-popconfirm title="确定删除？" @confirm="removeCategory('tvshow',item.id)"><a-button danger type="text">删除</a-button></a-popconfirm></a-list-item></template></a-list></a-col></a-row></a-card><a-modal v-model:open="categoryVisible" :title="categoryType==='movie'?'电影分类':'电视剧分类'" @ok="saveCategory"><a-form layout="vertical"><a-form-item label="名称"><a-input v-model:value="category.name"/></a-form-item><a-form-item :label="categoryType==='movie'?'语言代码':'国家代码'"><a-select v-model:value="category.regions" mode="tags"/></a-form-item><a-form-item label="TMDB 类型 ID"><a-select v-model:value="category.genres" mode="tags"/></a-form-item></a-form></a-modal></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{message}from'ant-design-vue';import{del,get,post}from'../../services/http';import type{AnyMap}from'../../types';const tmdb=reactive<AnyMap>({}),ai=reactive<AnyMap>({ai_timeout:60}),movie=ref<AnyMap[]>([]),tv=ref<AnyMap[]>([]),categoryVisible=ref(false),categoryType=ref('movie'),category=reactive({name:'',regions:[] as string[],genres:[] as string[]});async function load(){const[t,a,m,v]=await Promise.all([get<AnyMap>('/scrape/tmdb'),get<AnyMap>('/scrape/ai-settings'),get<AnyMap[]>('/scrape/movie-categories'),get<AnyMap[]>('/scrape/tvshow-categories')]);Object.assign(tmdb,t);Object.assign(ai,a);movie.value=m;tv.value=v}const saveTmdb=async()=>{await post('/scrape/tmdb',tmdb);message.success('TMDB 设置已保存')},saveAi=async()=>{await post('/scrape/ai-settings',ai);message.success('AI 设置已保存')},testTmdb=()=>post('/scrape/tmdb-test',tmdb).then(()=>message.success('TMDB 连接正常')),testAi=()=>post('/scrape/ai-test',ai).then(()=>message.success('AI 连接正常'));function openCategory(type:string){categoryType.value=type;Object.assign(category,{name:'',regions:[],genres:[]});categoryVisible.value=true}async function saveCategory(){const movieType=categoryType.value==='movie';await post(`/scrape/${movieType?'movie':'tvshow'}-categories`,{name:category.name,genre_id_array:category.genres.map(Number),[movieType?'language_array':'country_array']:category.regions});categoryVisible.value=false;load()}async function removeCategory(type:string,id:number){await del(`/scrape/${type==='movie'?'movie':'tvshow'}-categories/${id}`);load()}onMounted(load)</script><style scoped>.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.categories{margin-top:18px}</style>
